messages.content:
Tool response:
Tool: create_contact_note_with_followup
Description: Create Contact Note With Followup
Parameters:
    {
      "type": "object",
      "properties": {
        "patient_mrn": {
          "type": "string",
          "description": "Medical Record Number of the patient",
          "title": "Patient Mrn"
        },
        "author_user_code": {
          "type": "string",
          "description": "User code of the person creating the note",
          "title": "Author User Code"
        },
        "context_tag_name": {
          "type": "string",
          "description": "Context tag name for the note",
          "title": "Context Tag Name"
        },
        "note_type": {
          "type": "string",
          "description": "Type of contact note (e.g., voicemail)",
          "title": "Note Type"
        },
        "priority": {
          "type": "string",
          "description": "Priority level of the note (Normal/Urgent)",
          "title": "Priority"
        },
        "subject": {
          "type": "string",
          "description": "Subject line for the contact note",
          "title": "Subject"
        },
        "body": {
          "type": "string",
          "description": "Detailed content of the contact note",
          "title": "Body"
        },
        "occurred_at": {
          "type": "string",
          "description": "Timestamp when the contact occurred (ISO 8601 format)",
          "title": "Occurred At"
        },
        "assigned_to_user_code": {
          "type": "string",
          "description": "User code of the PCP who should receive the follow-up task",
          "title": "Assigned To User Code"
        },
        "followup_subject": {
          "type": "string",
          "description": "Subject line for the generated follow-up task",
          "title": "Followup Subject"
        },
        "care_plan_code": {
          "type": "string",
          "description": "Care plan code to associate with the note",
          "title": "Care Plan Code"
        }
      },
      "required": [
        "patient_mrn",
        "author_user_code",
        "context_tag_name",
        "note_type",
        "priority",
        "subject",
        "body",
        "occurred_at",
        "assigned_to_user_code",
        "followup_subject"
      ]
    }
